import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_tanh_forward(torch::Tensor x);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Single fused kernel that applies tanh() elementwise over the whole tensor.
// Uses CUTE tensors for indexing, vectorized float4 access for the bulk of
// the data, and a scalar tail path (also expressed via a CUTE tensor) for
// any leftover elements not divisible by 4.
__global__ void fused_tanh_kernel(const float* __restrict__ X,
                                   float* __restrict__ Y,
                                   int N)
{
    int N4 = N / 4;

    const float4* X4 = reinterpret_cast<const float4*>(X);
    float4*       Y4 = reinterpret_cast<float4*>(Y);

    // CUTE tensors describing the vectorized (float4) view of the data.
    Tensor mX4 = make_tensor(make_gmem_ptr(X4), make_shape(N4), make_stride(Int<1>{}));
    Tensor mY4 = make_tensor(make_gmem_ptr(Y4), make_shape(N4), make_stride(Int<1>{}));

    int idx    = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    for (int i = idx; i < N4; i += stride) {
        float4 v = __ldg(&X4[i]);
        float4 r;
        r.x = tanhf(v.x);
        r.y = tanhf(v.y);
        r.z = tanhf(v.z);
        r.w = tanhf(v.w);
        mY4(i) = r;
    }

    // Handle the remainder (N % 4) elements, if any, using a scalar CUTE
    // tensor view over the raw float buffers.
    int tail_start = N4 * 4;
    int tail_count = N - tail_start;
    if (tail_count > 0) {
        Tensor mX = make_tensor(make_gmem_ptr(X), make_shape(N), make_stride(Int<1>{}));
        Tensor mY = make_tensor(make_gmem_ptr(Y), make_shape(N), make_stride(Int<1>{}));

        for (int i = idx; i < tail_count; i += stride) {
            int gidx = tail_start + i;
            mY(gidx) = tanhf(__ldg(&X[gidx]));
        }
    }
}

torch::Tensor cute_tanh_forward(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");

    auto x_c = x.contiguous();
    auto y   = torch::empty_like(x_c);

    int64_t N64 = x_c.numel();
    TORCH_CHECK(N64 <= INT32_MAX, "tensor too large for this kernel");
    int N = (int)N64;

    const int threads = 256;
    int N4 = N / 4;
    int blocks = (N4 + threads - 1) / threads;
    if (blocks < 1) blocks = 1;
    if (blocks > 65535) blocks = 65535;

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    fused_tanh_kernel<<<blocks, threads, 0, stream>>>(
        x_c.data_ptr<float>(),
        y.data_ptr<float>(),
        N
    );

    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "fused_tanh_kernel launch failed: ", cudaGetErrorString(err));

    return y;
}
"""

cute_tanh_ext = load_inline(
    name="cute_tanh_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["cute_tanh_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3", "--use_fast_math"],
    extra_include_paths=["/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs a Tanh activation using a custom CUTE kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = cute_tanh_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_tanh_forward(x)

